'use strict';

const SOURCE_KEY = 'legado.sources.v2';
const LEGACY_SOURCE_KEY = 'legado.sources.v1';
const ACTIVE_SOURCE_KEY = 'legado.activeSource.v2';
const LEGACY_ACTIVE_SOURCE_KEY = 'legado.activeSource.v1';
const ACTIVE_SOURCE_RECORD_KEY = 'legado.activeSourceRecord.v3';
const CATALOG_CACHE_VERSION = 2;
const CATALOG_CHUNK_MAXIMUM_BYTES = 384 * 1024;
const DEFAULT_HOSTS = [
  'https://v5.czyl.cf', 'https://api.langge.cf', 'http://219.154.201.122:5006',
  'https://20.langge.tk', 'https://v4.czyl.cf', 'https://v2.czyl.cf',
  'https://v7.czyl.cf', 'https://v8.czyl.cf', 'https://v9.czyl.cf', 'https://v10.czyl.cf'
];

function text(value) {
  if (value === undefined || value === null) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'object') {
    try { return JSON.stringify(value); } catch (_) {}
  }
  return String(value);
}

function object(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function sourceRuleTemplate(source) {
  const item = object(source);
  const currentNames = ['ruleSearch', 'ruleExplore', 'ruleBookInfo', 'ruleToc', 'ruleContent'];
  const legacyNames = ['searchRule', 'exploreRule', 'bookInfoRule', 'tocRule', 'contentRule'];
  const current = currentNames.some(name => item[name] !== undefined && item[name] !== null);
  const legacy = !current && legacyNames.some(name => item[name] !== undefined && item[name] !== null);
  return current ? {
    version: 'current', search: object(item.ruleSearch), explore: object(item.ruleExplore),
    bookInfo: object(item.ruleBookInfo), toc: object(item.ruleToc), content: object(item.ruleContent),
    bookList: object(item.ruleBookList)
  } : {
    version: legacy ? 'legacy' : 'current', search: object(item.searchRule),
    explore: object(item.exploreRule), bookInfo: object(item.bookInfoRule),
    toc: object(item.tocRule), content: object(item.contentRule),
    bookList: object(item.bookListRule)
  };
}

function sourceNetworkUrl(source) {
  return text(source && source.bookSourceUrl).replace(/#.*$/, '');
}

function resultSourceName(value) {
  const item = object(value);
  const raw = item.sourceName || item.source_name || item.source || item.originName ||
    item.origin_name || item.origin || item.siteName || item.site_name || item.site;
  if (raw && typeof raw === 'object') return text(raw.name || raw.title || raw.id).trim().slice(0, 512);
  return text(raw).trim().slice(0, 512);
}

function resultSourceDisplayName(source, value) {
  const parent = text(source && (source.bookSourceName || source.bookSourceUrl)).trim().slice(0, 512);
  const child = resultSourceName(value);
  if (!child || child === parent || parent.includes(child)) return parent || child;
  if (child.includes(parent)) return child;
  return `${parent}•${child}`;
}

function leadingJsonValue(value) {
  const raw = text(value).trim();
  if (!raw || (!raw.startsWith('{') && !raw.startsWith('['))) return '';
  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let index = 0; index < raw.length; index++) {
    const character = raw[index];
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quoted = false;
      continue;
    }
    if (character === '"') quoted = true;
    else if (character === '{' || character === '[') depth++;
    else if (character === '}' || character === ']') {
      depth--;
      if (depth === 0) return raw.slice(0, index + 1);
      if (depth < 0) return '';
    }
  }
  return '';
}

function structuredChapterContent(value) {
  const raw = text(value).trim();
  const jsonValue = leadingJsonValue(raw);
  if (!jsonValue) return null;
  let parsed;
  try { parsed = JSON.parse(jsonValue); } catch (_) { return null; }
  if (!parsed || typeof parsed !== 'object') return null;
  const sample = Array.isArray(parsed) ? object(parsed.find(item => item && typeof item === 'object')) : object(parsed);
  const videoKeys = ['vid', 'video_size', 'videoSize', 'video_url', 'videoUrl', 'video_list', 'videoList'];
  const audioKeys = ['audio_url', 'audioUrl', 'audio_list', 'audioList', 'mp3', 'm4a'];
  const contentType = videoKeys.some(key => sample[key] !== undefined) ? 'video' :
    (audioKeys.some(key => sample[key] !== undefined) ? 'audio' : 'structured');
  const mediaCandidate = text(sample.videoUrl || sample.video_url || sample.audioUrl ||
    sample.audio_url || sample.playUrl || sample.play_url || sample.url).trim();
  const mediaUrl = /^https?:\/\//i.test(mediaCandidate) ? mediaCandidate.slice(0, 4096) : '';
  const message = contentType === 'video' ? '该章节为视频内容，当前阅读器暂不支持播放' :
    (contentType === 'audio' ? '该章节为音频内容，当前阅读器暂不支持播放' :
      '该章节返回结构化接口数据，未识别为可阅读正文');
  return { content: '', contentType, mediaUrl, message };
}

function databaseQuery(sql, bindArgs, maximumRows) {
  if (!reader.database || typeof reader.database.query !== 'function') return null;
  try {
    const result = object(reader.database.query({
      sql,
      bindArgs: Array.isArray(bindArgs) ? bindArgs : [],
      maximumRows: maximumRows || 500
    }));
    reader.storage.set('legado.databaseError.v1', '');
    return result;
  } catch (error) {
    // Older hosts and a freshly installed plugin may not have the source table yet.
    try {
      reader.storage.set('legado.databaseError.v1',
        text(error && error.message ? error.message : error).slice(0, 1000));
    } catch (_) {}
    return null;
  }
}

function databaseExecute(sql, bindArgs) {
  if (!reader.database || typeof reader.database.execute !== 'function') return false;
  try {
    reader.database.execute({ sql, bindArgs: Array.isArray(bindArgs) ? bindArgs : [] });
    return true;
  } catch (_) {
    return false;
  }
}

function databaseSourceByKey(key) {
  const result = databaseQuery(
    'SELECT source_json FROM legado_sources WHERE source_key = ?', [key], 1);
  if (!result || !Array.isArray(result.rows) || result.rows.length === 0) return null;
  try { return object(JSON.parse(text(result.rows[0].source_json))); } catch (_) { return null; }
}

function databaseFirstEnabledSource() {
  const result = databaseQuery(
    'SELECT source_json FROM legado_sources WHERE enabled = 1 ORDER BY import_order ASC LIMIT 1', [], 1);
  if (!result || !Array.isArray(result.rows) || result.rows.length === 0) return null;
  try { return object(JSON.parse(text(result.rows[0].source_json))); } catch (_) { return null; }
}

function databaseSourceTargets(capability) {
  const targets = [];
  for (let offset = 0; ; offset += 500) {
    const result = databaseQuery(
      'SELECT source_key, name, source_json FROM legado_sources WHERE enabled = 1 ' +
      'ORDER BY import_order ASC LIMIT 500 OFFSET ' + offset, [], 500);
    if (!result || !Array.isArray(result.rows)) return null;
    for (const row of result.rows) {
      let source = {};
      try { source = object(JSON.parse(text(row.source_json))); } catch (_) { continue; }
      if (!text(source[capability]).trim()) continue;
      targets.push({
        sourceKey: text(row.source_key || source.bookSourceUrl || source.bookSourceName),
        name: text(row.name || source.bookSourceName || source.bookSourceUrl)
      });
    }
    if (result.rows.length < 500) break;
  }
  return targets;
}

function domainsFromSource(source) {
  let serialized = '';
  try { serialized = JSON.stringify(source); } catch (_) { return []; }
  const urls = serialized.match(/https?:\/\/[A-Za-z0-9.-]+(?::\d+)?/gi) || [];
  const domains = [];
  for (const raw of urls) {
    const match = raw.match(/^https?:\/\/([^/:?#]+)/i);
    const domain = text(match && match[1]).trim().toLowerCase().replace(/\.+$/, '');
    if (domain && !domains.includes(domain)) domains.push(domain);
  }
  return domains;
}

function permissionGroup(source, sourceKey, name) {
  const domains = domainsFromSource(source);
  const title = text(name || source.bookSourceName || source.bookSourceUrl || '未命名书源');
  const key = text(sourceKey || source.bookSourceUrl || source.bookSourceName || `source:${title}`);
  return {
    key,
    title,
    domains
  };
}

function databasePermissionGroups() {
  const groups = [];
  for (let offset = 0; ; offset += 500) {
    const result = databaseQuery(
      'SELECT source_key, name, source_json FROM legado_sources ' +
      'ORDER BY import_order ASC LIMIT 500 OFFSET ' + offset, [], 500);
    if (!result || !Array.isArray(result.rows)) return null;
    for (const row of result.rows) {
      let source = {};
      try { source = object(JSON.parse(text(row.source_json))); } catch (_) { continue; }
      groups.push(permissionGroup(source, row.source_key, row.name));
    }
    if (result.rows.length < 500) break;
  }
  return groups;
}

function sourceConfig() {
  const raw = reader.source.getVariable();
  if (!raw) return {};
  try { return object(JSON.parse(raw)); } catch (_) { return {}; }
}

function importedSources() {
  const stored = reader.storage.get(SOURCE_KEY) || reader.storage.get(LEGACY_SOURCE_KEY);
  return Array.isArray(stored) ? stored : [];
}

function activeSource() {
  const activeRecord = reader.storage.get(ACTIVE_SOURCE_RECORD_KEY);
  if (activeRecord && typeof activeRecord === 'object' && activeRecord.enabled !== false) {
    return object(activeRecord);
  }
  const databaseSource = databaseFirstEnabledSource();
  if (databaseSource) return databaseSource;
  const sources = importedSources().filter(item => item.enabled !== false);
  if (sources.length === 0) throw new Error('请先打开插件页面导入阅读书源');
  const activeUrl = text(reader.storage.get(ACTIVE_SOURCE_KEY) ||
    reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
  return object(sources.find(item => text(item.bookSourceUrl) === activeUrl) || sources[0]);
}

function availableHosts(source) {
  const config = sourceConfig();
  const preferred = text(config.server).trim();
  const matches = text(source.jsLib).match(/https?:\/\/[A-Za-z0-9.:-]+/g) || [];
  const hosts = [...new Set([...matches, ...DEFAULT_HOSTS])];
  return preferred ? [preferred, ...hosts.filter(item => item !== preferred)] : hosts;
}

function fetchHost(source, path, request) {
  let lastError = '没有可用线路';
  for (const host of availableHosts(source)) {
    try {
      const response = reader.http.fetch(Object.assign({}, request, { url: host + path }));
      if (response && response.status >= 200 && response.status < 400) {
        const parsed = JSON.parse(response.body || '{}');
        if (parsed && Number(parsed.code || 0) === 0) {
          reader.storage.set('legado.activeHost.v1', host);
          return { host, data: parsed };
        }
        lastError = text(parsed && (parsed.msg || parsed.message)) || ('HTTP ' + response.status);
      }
    } catch (error) {
      lastError = text(error && error.message ? error.message : error);
    }
  }
  throw new Error('阅读兼容线路请求失败：' + lastError);
}

function query(values) {
  return Object.keys(values).map(key => encodeURIComponent(key) + '=' +
    encodeURIComponent(text(values[key]))).join('&');
}

function stored(key) {
  return object(reader.storage.get(key));
}

function utf8ByteLength(value) {
  try { return unescape(encodeURIComponent(text(value))).length; } catch (_) {
    return text(value).length * 3;
  }
}

function firstData(value) {
  const source = object(value);
  return source.data && !Array.isArray(source.data) ? object(source.data) : source;
}

function bookKey(item) {
  return 'legado.book.' + encodeURIComponent(text(item.source || 'source')).slice(0, 80) + '.' +
    encodeURIComponent(text(item.book_id || item.id)).slice(0, 160);
}

function chapterKey(bookIdentity, item, index) {
  return 'legado.chapter.' + encodeURIComponent(text(item.item_id || item.id || index)).slice(0, 180) + '.' +
    encodeURIComponent(bookIdentity).slice(-160);
}

function sourceIdentity(source) {
  const input = text(source.bookSourceUrl || source.bookSourceName);
  let hash = 2166136261;
  for (let index = 0; index < input.length; index++) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16);
}

function ruleFingerprint(value) {
  return sourceIdentity({ bookSourceUrl: JSON.stringify(value) });
}

function detailResult(identity, detail, source, rules, result, fieldEnv) {
  return { bookKey: identity, title: detail.title || '未命名书籍', author: detail.author,
    sourceName: text(detail.sourceName),
    intro: detail.intro, coverUrl: detail.coverUrl, bookUrl: identity, tocUrl: identity,
    kind: text(ruleValue(source, rules.kind, result, fieldEnv, false)),
    latestChapter: text(ruleValue(source, rules.lastChapter, result, fieldEnv, false)),
    wordCount: text(ruleValue(source, rules.wordCount, result, fieldEnv, false)),
    lastUpdated: text(ruleValue(source, rules.updateTime, result, fieldEnv, false)),
    canReName: detail.canReName, downloadUrls: detail.downloadUrls };
}

function catalogStorageKey(sourceHash, bookHash, generation, chunkIndex) {
  return `legado.catalog.v2.${sourceHash}.${bookHash}.${generation}.${chunkIndex}`;
}

function detailCacheKey(identity) {
  return text(identity) + '.detail-cache.v2';
}

function catalogCacheKey(identity) {
  return text(identity) + '.catalog-cache.v2';
}

function catalogChapterKey(sourceHash, bookHash, generation, chunkIndex, itemIndex) {
  return `legado.chapter.v2.${sourceHash}.${bookHash}.${generation}.${chunkIndex}.${itemIndex}`;
}

function publicChapter(chapter) {
  return { chapterKey: text(chapter.chapterKey), title: text(chapter.title),
    ordinal: Number(chapter.index || 0), chapterUrl: text(chapter.chapterKey),
    isVolume: chapter.isVolume === true, isLocked: chapter.isLocked === true };
}

function cachedCatalog(identity, fingerprint) {
  const cache = stored(catalogCacheKey(identity));
  if (cache.version !== CATALOG_CACHE_VERSION || text(cache.fingerprint) !== fingerprint ||
      !Array.isArray(cache.chunkKeys) || Number(cache.chapterCount) < 1) return null;
  const chapters = [];
  for (const key of cache.chunkKeys) {
    const chunk = reader.storage.get(text(key));
    if (!Array.isArray(chunk)) return null;
    for (const chapter of chunk) chapters.push(object(chapter));
  }
  if (chapters.length !== Number(cache.chapterCount)) return null;
  return chapters.map(publicChapter);
}

function storeCatalogSnapshot(source, identity, fingerprint, chapters) {
  const sourceHash = sourceIdentity(source);
  const bookHash = sourceIdentity({ bookSourceUrl: identity });
  const generation = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  const chunks = [];
  let chunk = [], chunkBytes = 2;
  for (const chapter of chapters) {
    const encoded = JSON.stringify(chapter);
    const itemBytes = utf8ByteLength(encoded) + 1;
    if (chunk.length > 0 && chunkBytes + itemBytes > CATALOG_CHUNK_MAXIMUM_BYTES) {
      chunks.push(chunk);
      chunk = [];
      chunkBytes = 2;
    }
    const chunkIndex = chunks.length;
    chapter.chapterKey = catalogChapterKey(sourceHash, bookHash, generation, chunkIndex, chunk.length);
    chunk.push(chapter);
    chunkBytes += itemBytes + utf8ByteLength(chapter.chapterKey);
  }
  if (chunk.length > 0) chunks.push(chunk);
  const chunkKeys = chunks.map((_value, index) =>
    catalogStorageKey(sourceHash, bookHash, generation, index));
  chunks.forEach((value, index) => reader.storage.set(chunkKeys[index], value));
  reader.storage.set(catalogCacheKey(identity), { version: CATALOG_CACHE_VERSION, fingerprint,
    chapterCount: chapters.length, chunkKeys, updatedAtMs: Date.now() });
  return chapters.map(publicChapter);
}

function snapshotChapter(key) {
  const match = text(key).match(/^legado\.chapter\.v2\.([^.]+)\.([^.]+)\.([^.]+)\.(\d+)\.(\d+)$/);
  if (!match) return {};
  const chunk = reader.storage.get(catalogStorageKey(match[1], match[2], match[3], Number(match[4])));
  return Array.isArray(chunk) ? object(chunk[Number(match[5])]) : {};
}

function sourceStorageKey(source, name) {
  return 'legado.source.' + sourceIdentity(source) + '.' + name;
}

function sourceByKey(key) {
  return databaseSourceByKey(key) ||
    importedSources().find(item => text(item.bookSourceUrl || item.bookSourceName) === key) || null;
}

function sourceForInput(input) {
  const request = object(input);
  let key = text(request.sourceKey).trim();
  if (!key) {
    const identity = text(request.bookKey || request.chapterKey || request.tocUrl ||
      request.chapterUrl || request.bookUrl).trim();
    if (identity) {
      const saved = stored(identity);
      key = text(saved.sourceKey).trim();
      if (!key && saved.bookKey) key = text(stored(text(saved.bookKey)).sourceKey).trim();
    }
  }
  return (key ? sourceByKey(key) : null) || activeSource();
}

function normalizeImportedSourceList(value) {
  const list = Array.isArray(value) ? value :
    (value && Array.isArray(value.bookSources) ? value.bookSources : [value]);
  return list.filter(item => item && typeof item === 'object' &&
    text(item.bookSourceUrl || item.bookSourceName).trim());
}

function jsonObject(raw, fallback) {
  try {
    const value = typeof raw === 'string' ? JSON.parse(raw) : raw;
    return object(value);
  } catch (_) {
    return fallback || {};
  }
}

function normalizeTarget(raw) {
  const value = text(raw).trim();
  if (/^https?:\/\//i.test(value)) return value;
  return 'https://' + value.replace(/^\/+/, '');
}

function parseCookie(header, name) {
  const prefix = name + '=';
  const found = text(header).split(';').map(item => item.trim())
    .find(item => item.startsWith(prefix));
  return found ? found.slice(prefix.length) : '';
}

function parseAjaxRequest(raw, source, env) {
  let target = text(raw).trim();
  let options = {};
  const marker = target.lastIndexOf(',{');
  if (marker > 0) {
    try {
      options = object(JSON.parse(target.slice(marker + 1)));
      target = target.slice(0, marker);
    } catch (_) {}
  }
  if (options.js && source) {
    target = text(evaluateJs(source, options.js, Object.assign({}, env, { result: target, baseUrl: target }))) || target;
  }
  const method = text(options.method || (options.body !== undefined ? 'POST' : 'GET')).toUpperCase();
  const headers = typeof options.headers === 'string' ? jsonObject(options.headers, {}) : object(options.headers);
  let body = options.body;
  if (body !== undefined && body !== null && typeof body !== 'string') {
    body = JSON.stringify(body);
    if (!Object.keys(headers).some(key => key.toLowerCase() === 'content-type')) {
      headers['Content-Type'] = 'application/json';
    }
  }
  return { url: target, method, headers, body: body === undefined ? undefined : text(body),
    retry: Math.max(0, Math.min(10, Number(options.retry || 0))), bodyJs: text(options.bodyJs),
    webView: !(options.webView === undefined || options.webView === null || options.webView === '' ||
      options.webView === false || options.webView === 'false'),
    webJs: text(options.webJs), type: text(options.type), charset: text(options.charset),
    webViewDelayTime: Math.max(0, Math.min(30000, Number(options.webViewDelayTime || 0))) };
}

function utf8Base64(input) {
  const bytes = unescape(encodeURIComponent(text(input)));
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  let output = '';
  for (let index = 0; index < bytes.length; index += 3) {
    const a = bytes.charCodeAt(index), b = bytes.charCodeAt(index + 1), c = bytes.charCodeAt(index + 2);
    output += chars[a >> 2] + chars[((a & 3) << 4) | (b >> 4)] +
      (Number.isNaN(b) ? '=' : chars[((b & 15) << 2) | (c >> 6)]) +
      (Number.isNaN(c) ? '=' : chars[c & 63]);
  }
  return output;
}

function base64Utf8(input) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  const clean = text(input).replace(/[^A-Za-z0-9+/=]/g, '');
  let bytes = '';
  for (let index = 0; index < clean.length; index += 4) {
    const a = chars.indexOf(clean[index]), b = chars.indexOf(clean[index + 1]);
    const c = chars.indexOf(clean[index + 2]), d = chars.indexOf(clean[index + 3]);
    bytes += String.fromCharCode((a << 2) | (b >> 4));
    if (c >= 0 && c !== 64) bytes += String.fromCharCode(((b & 15) << 4) | (c >> 2));
    if (d >= 0 && d !== 64) bytes += String.fromCharCode(((c & 3) << 6) | d);
  }
  try { return decodeURIComponent(escape(bytes)); } catch (_) { return bytes; }
}

function base64ByteArray(input) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=';
  const clean = text(input).replace(/[^A-Za-z0-9+/=]/g, '');
  const output = [];
  for (let index = 0; index < clean.length; index += 4) {
    const a = chars.indexOf(clean[index]), b = chars.indexOf(clean[index + 1]);
    const c = chars.indexOf(clean[index + 2]), d = chars.indexOf(clean[index + 3]);
    if (a < 0 || b < 0) break;
    output.push(((a << 2) | (b >> 4)) & 255);
    if (c >= 0 && c !== 64) output.push((((b & 15) << 4) | (c >> 2)) & 255);
    if (d >= 0 && d !== 64) output.push((((c & 3) << 6) | d) & 255);
  }
  Object.defineProperty(output, 'toArray', { value: () => output.slice(), enumerable: false });
  return output;
}

function listCompat(values) {
  const output = Array.isArray(values) ? values : [];
  if (typeof output.toArray !== 'function') {
    Object.defineProperty(output, 'toArray', { value: () => output.slice(), enumerable: false });
  }
  return output;
}

function stripMarkup(value) {
  return htmlDecode(text(value).replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '').replace(/<[^>]+>/g, ' '))
    .replace(/\s+/g, ' ').trim();
}

function elementCompat(value) {
  if (value !== null && typeof value === 'object') return value;
  const raw = text(value);
  return {
    attr: name => {
      const key = text(name).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const match = raw.match(new RegExp('\\s' + key + '\\s*=\\s*(["\\\'])([\\s\\S]*?)\\1', 'i')) ||
        raw.match(new RegExp('\\s' + key + '\\s*=\\s*([^\\s>]+)', 'i'));
      return match ? htmlDecode(match[2] === undefined ? match[1] : match[2]) : '';
    },
    text: () => stripMarkup(raw),
    html: () => {
      const match = raw.match(/^<[^>]+>([\s\S]*)<\/[^>]+>$/);
      return match ? match[1] : raw;
    },
    outerHtml: () => raw,
    toString: () => raw
  };
}

function elementsCompat(values) {
  const output = listCompat((Array.isArray(values) ? values : []).map(elementCompat));
  output.attr = name => output.length > 0 && typeof output[0].attr === 'function' ? output[0].attr(name) : '';
  output.text = () => output.map(value => typeof value.text === 'function' ? value.text() : text(value)).join(' ');
  output.html = () => output.map(value => typeof value.html === 'function' ? value.html() : text(value)).join('\n');
  return output;
}

function chineseNumberValue(value) {
  const digits = { '零': 0, '〇': 0, '一': 1, '二': 2, '两': 2, '三': 3, '四': 4,
    '五': 5, '六': 6, '七': 7, '八': 8, '九': 9 };
  const units = { '十': 10, '百': 100, '千': 1000, '万': 10000, '亿': 100000000 };
  let total = 0, section = 0, number = 0, usedUnit = false;
  for (const char of text(value)) {
    if (digits[char] !== undefined) { number = digits[char]; continue; }
    const unit = units[char];
    if (!unit) continue;
    usedUnit = true;
    if (unit < 10000) { section += (number || 1) * unit; number = 0; }
