    if (token.type === 'index' && previousType === 'filter') {
      const index = token.value < 0 ? values.length + token.value : token.value;
      values = values[index] === undefined ? [] : [values[index]];
      previousType = token.type;
      continue;
    }
    const next = [];
    for (const item of values) applyJsonPathToken(item, token, next);
    values = next;
    previousType = token.type;
  }
  return values.length === 0 ? null : (values.length === 1 ? values[0] : values);
}

function parseJsonPathTokens(rule) {
  const tokens = [];
  let index = 0;
  while (index < rule.length) {
    if (rule.startsWith('..', index)) {
      index += 2;
      const match = rule.slice(index).match(/^([A-Za-z_$][\w$-]*|\*)/);
      if (!match) break;
      tokens.push({ type: 'recursive', value: match[1] });
      index += match[1].length;
      continue;
    }
    if (rule[index] === '.') {
      index++;
      const match = rule.slice(index).match(/^([A-Za-z_$][\w$-]*|\*)/);
      if (!match) continue;
      tokens.push({ type: match[1] === '*' ? 'wildcard' : 'property', value: match[1] });
      index += match[1].length;
      continue;
    }
    if (rule[index] === '[') {
      const end = findBalanced(rule, index, '[', ']');
      if (end < 0) break;
      const body = rule.slice(index + 1, end).trim();
      if (body === '*') tokens.push({ type: 'wildcard' });
      else if (/^-?\d+$/.test(body)) tokens.push({ type: 'index', value: Number(body) });
      else if (/^-?\d*:-?\d*(?::-?\d+)?$/.test(body)) {
        const parts = body.split(':');
        tokens.push({ type: 'slice', start: parts[0] === '' ? null : Number(parts[0]),
          end: parts[1] === '' ? null : Number(parts[1]), step: parts[2] ? Number(parts[2]) : 1 });
      } else if (body.startsWith('?(') && body.endsWith(')')) {
        tokens.push({ type: 'filter', value: body.slice(2, -1).trim() });
      } else {
        const names = body.split(',').map(value => value.trim().replace(/^['"]|['"]$/g, ''));
        tokens.push({ type: 'union', value: names });
      }
      index = end + 1;
      continue;
    }
    const match = rule.slice(index).match(/^([A-Za-z_$][\w$-]*)/);
    if (match) {
      tokens.push({ type: 'property', value: match[1] });
      index += match[1].length;
    } else index++;
  }
  return tokens;
}

function findBalanced(value, start, open, close) {
  let depth = 0, quote = '';
  for (let index = start; index < value.length; index++) {
    const char = value[index];
    if (quote) {
      if (char === quote && value[index - 1] !== '\\') quote = '';
      continue;
    }
    if (char === '"' || char === "'") { quote = char; continue; }
    if (char === open) depth++;
    else if (char === close && --depth === 0) return index;
  }
  return -1;
}

function applyJsonPathToken(item, token, output) {
  if (item === null || item === undefined) return;
  if (token.type === 'property') {
    if (item[token.value] !== undefined) output.push(item[token.value]);
    return;
  }
  if (token.type === 'index') {
    if (!Array.isArray(item)) return;
    const index = token.value < 0 ? item.length + token.value : token.value;
    if (item[index] !== undefined) output.push(item[index]);
    return;
  }
  if (token.type === 'wildcard') {
    if (Array.isArray(item)) output.push(...item);
    else if (typeof item === 'object') output.push(...Object.values(item));
    return;
  }
  if (token.type === 'union') {
    for (const name of token.value) {
      const index = /^-?\d+$/.test(name) && Array.isArray(item) ? Number(name) : name;
      const resolved = typeof index === 'number' && index < 0 ? item.length + index : index;
      if (item[resolved] !== undefined) output.push(item[resolved]);
    }
    return;
  }
  if (token.type === 'slice') {
    if (!Array.isArray(item)) return;
    const start = token.start === null ? (token.step < 0 ? item.length - 1 : 0) :
      (token.start < 0 ? item.length + token.start : token.start);
    const end = token.end === null ? (token.step < 0 ? -1 : item.length) :
      (token.end < 0 ? item.length + token.end : token.end);
    for (let index = start; token.step < 0 ? index > end : index < end; index += token.step) {
      if (item[index] !== undefined) output.push(item[index]);
    }
    return;
  }
  if (token.type === 'filter') {
    const candidates = Array.isArray(item) ? item : Object.values(object(item));
    candidates.filter(value => jsonPathFilter(value, token.value)).forEach(value => output.push(value));
    return;
  }
  if (token.type === 'recursive') collectRecursive(item, token.value, output);
}

function collectRecursive(value, name, output) {
  if (value === null || value === undefined || typeof value !== 'object') return;
  for (const [key, item] of Object.entries(value)) {
    if (name === '*' || key === name) output.push(item);
    collectRecursive(item, name, output);
  }
}

function jsonPathFilter(item, expression) {
  const match = text(expression).match(/^@(?:\.([A-Za-z_$][\w$-]*))?\s*(?:(==|!=|>=|<=|>|<|=~)\s*([\s\S]+))?$/);
  if (!match) return false;
  const actual = match[1] ? object(item)[match[1]] : item;
  if (!match[2]) return actual !== undefined && actual !== null;
  let expected = match[3].trim();
  if (/^['"][\s\S]*['"]$/.test(expected)) expected = expected.slice(1, -1);
  else if (expected === 'true' || expected === 'false') expected = expected === 'true';
  else if (expected === 'null') expected = null;
  else if (/^-?\d+(?:\.\d+)?$/.test(expected)) expected = Number(expected);
  if (match[2] === '=~') {
    const regex = text(expected).match(/^\/(.*)\/([gimsuy]*)$/);
    try { return regex ? new RegExp(regex[1], regex[2]).test(text(actual)) : false; } catch (_) { return false; }
  }
  if (match[2] === '==') return actual == expected;
  if (match[2] === '!=') return actual != expected;
  if (match[2] === '>=') return actual >= expected;
  if (match[2] === '<=') return actual <= expected;
  if (match[2] === '>') return actual > expected;
  return actual < expected;
}

function splitReplacement(rule) {
  const parts = text(rule).split('##');
  return { rule: parts[0], regex: parts.length > 1 ? parts[1] : '',
    replacement: parts.length > 2 ? parts[2] : '', first: parts.length > 3 };
}

function replaceRule(value, replacement) {
  if (!replacement.regex) return value;
  try {
    const flags = replacement.first ? '' : 'g';
    const regex = new RegExp(replacement.regex, flags);
    const input = text(value);
    if (replacement.first) {
      const match = input.match(regex);
      return match ? text(match[0]).replace(regex, replacement.replacement) : '';
    }
    return input.replace(regex, replacement.replacement);
  } catch (_) { return text(value).split(replacement.regex).join(replacement.replacement); }
}

function splitCombinedRule(rule, separator) {
  const output = [];
  let start = 0, quote = '', square = 0, round = 0, brace = 0;
  const value = text(rule);
  if (/^@js:/i.test(value.trim())) return [];
  for (let index = 0; index <= value.length - separator.length; index++) {
    if (value.slice(index, index + 4).toLowerCase() === '<js>') {
      const close = value.toLowerCase().indexOf('</js>', index + 4);
      if (close < 0) return [];
      index = close + 4;
      continue;
    }
    const char = value[index];
    if (quote) {
      if (char === quote && value[index - 1] !== '\\') quote = '';
      continue;
    }
    if (char === '"' || char === "'" || char === '`') { quote = char; continue; }
    if (char === '[') square++;
    else if (char === ']') square = Math.max(0, square - 1);
    else if (char === '(') round++;
    else if (char === ')') round = Math.max(0, round - 1);
    else if (char === '{') brace++;
    else if (char === '}') brace = Math.max(0, brace - 1);
    if (square === 0 && round === 0 && brace === 0 && value.startsWith(separator, index)) {
      output.push(value.slice(start, index));
      index += separator.length - 1;
      start = index + 1;
    }
  }
  if (output.length > 0) output.push(value.slice(start));
  return output;
}

function normalizeLegacySelector(selector, legacy) {
  let value = text(selector).trim();
  if (!legacy) value = value.replace(/(^|\s)class\.([\w-]+)/g, '$1.$2');
  value = value.replace(/(^|\s)id\.([\w-]+)/g, '$1#$2')
    .replace(/:eq\(\s*(-?\d+)\s*\)/g, (_all, index) =>
      Number(index) < 0 ? ':last-child' : `:nth-child(${Number(index) + 1})`)
    .replace(/:first(?![-\w(])/g, ':first-child')
    .replace(/:last(?![-\w(])/g, ':last-child');
  if (legacy) {
    value = value.replace(/(^|[\s>+~,])class\.([A-Za-z_][\w-]*)((?:\s+[A-Za-z_][\w-]*(?![\w.-]))*)/g,
        (_all, prefix, first, rest) => prefix + '.' + first +
          (rest.trim() ? rest.trim().split(/\s+/).map(name => '.' + name).join('') : ''))
      .replace(/(^|[\s>+~,])tag\.([A-Za-z][\w-]*)/g, '$1$2')
      .replace(/([A-Za-z*][\w-]*|\.[A-Za-z_][\w-]*|#[A-Za-z_][\w-]*)\.(-?\d+)(?=$|[\s>+~])/g,
        (_all, target, index) => Number(index) < 0 ? `${target}:last-of-type` :
          `${target}:nth-of-type(${Number(index) + 1})`);
  }
  return value;
}

function parseHtmlWithSelectorContext(request, selector) {
  try {
    return reader.html.parse(request);
  } catch (error) {
    const normalized = text(selector).replace(/\s+/g, ' ').slice(0, 160);
    const message = text(error && error.message ? error.message : error).replace(/\s+/g, ' ').slice(0, 300);
    throw new Error(`CSS selector failed: ${normalized || '*'}; ${message || 'unknown host error'}`);
  }
}

function defaultSelector(rule, input, all, legacy) {
  const value = text(rule).replace(/^@css:/i, '').replace(/^@@/, '');
  let selectorRule = value;
  let tail = all === true ? 'outerHtml' : 'text';
  if (legacy && value.includes('@')) {
    const parts = value.split('@').map(item => item.trim()).filter(Boolean);
    const candidate = parts[parts.length - 1] || '';
    if (/^(?:text|textnodes|html|all|innerhtml|outerhtml|owntext|href|src|value|title|content|style|class|id|attr\.|data-)/i
      .test(candidate)) {
      tail = parts.pop();
    }
    selectorRule = parts.join(' ');
  } else {
    const marker = value.lastIndexOf('@');
    selectorRule = marker >= 0 ? value.slice(0, marker) : value;
    tail = marker >= 0 ? value.slice(marker + 1) : tail;
  }
  const excludedIndexes = [];
  let selectedIndex = null;
  if (legacy) {
    selectorRule = selectorRule.replace(/!(-?\d+(?::-?\d+)*)\s*$/, (_all, indexes) => {
      for (const index of indexes.split(':')) excludedIndexes.push(Number(index));
      return '';
    });
    selectorRule = selectorRule.replace(/\.(-?\d+)\s*$/, (_all, index) => {
      selectedIndex = Number(index);
      return '';
    });
  }
  const selector = normalizeLegacySelector(selectorRule, legacy) || '*';
  const request = { html: typeof input === 'string' ? input : JSON.stringify(input), selector,
    all: all === true || excludedIndexes.length > 0 || selectedIndex !== null, limit: 1000,
    value: all === true && tail === 'outerHtml' ? 'outerHTML' : 'text' };
  const filterIndexes = result => {
    if (excludedIndexes.length === 0 && selectedIndex === null) return result;
    const values = Array.isArray(result) ? result : (result === null || result === undefined ? [] : [result]);
    const blocked = new Set(excludedIndexes.map(index => index < 0 ? values.length + index : index));
    const filtered = values.filter((_item, index) => !blocked.has(index));
    if (selectedIndex !== null) {
      const index = selectedIndex < 0 ? filtered.length + selectedIndex : selectedIndex;
      const selected = filtered[index];
      return all === true ? (selected === undefined ? [] : [selected]) :
        (selected === undefined ? '' : selected);
    }
    return all === true ? filtered : (filtered[0] === undefined ? '' : filtered[0]);
  };
  const normalizeTextResult = result => {
    if (!legacy || !/^(text|textnodes)$/i.test(tail)) return result;
    const normalize = item => text(item).replace(/\s+/g, ' ').trim();
    return Array.isArray(result) ? result.map(normalize) : normalize(result);
  };
  if (/^(text|textnodes)$/i.test(tail)) request.value = 'text';
  else if (/^(html|all|innerhtml)$/i.test(tail)) request.value = 'innerHTML';
  else if (/^outerhtml$/i.test(tail)) request.value = 'outerHTML';
  else if (/^(owntext|ownText)$/i.test(tail)) {
    request.value = 'innerHTML';
    const found = parseHtmlWithSelectorContext(request, selector);
    const ownText = value => text(value).replace(/<[^>]+>[\s\S]*?<\/[^>]+>/g, '')
      .replace(/<[^>]+>/g, '').trim();
    return filterIndexes(normalizeTextResult(Array.isArray(found) ? found.map(ownText) : ownText(found)));
  } else { request.value = 'attribute'; request.attribute = tail.replace(/^attr\./i, ''); }
  return filterIndexes(normalizeTextResult(parseHtmlWithSelectorContext(request, selector)));
}

function xpathSelector(rule) {
  let value = text(rule).replace(/^@xpath:/i, '').trim();
  let tail = 'outerHtml';
  const attr = value.match(/\/@([A-Za-z_:][\w:.-]*)$/);
  if (attr) { tail = attr[1]; value = value.slice(0, -attr[0].length); }
  else if (/\/(?:text|string)\(\)$/.test(value)) {
    tail = 'text'; value = value.replace(/\/(?:text|string)\(\)$/, '');
  }
  const descendants = value.startsWith('//');
  const rawParts = value.replace(/^\/+/, '').split(/\/+?/).filter(Boolean);
  const parts = rawParts.map(part => {
    let selector = (part.match(/^[A-Za-z*][\w-]*/) || ['*'])[0];
    const predicates = part.match(/\[[^\]]+\]/g) || [];
    for (const raw of predicates) {
      const condition = raw.slice(1, -1).trim();
      let match = condition.match(/^@([\w:.-]+)\s*=\s*['"]([^'"]*)['"]$/);
      if (match) selector += `[${match[1]}="${match[2]}"]`;
      else if ((match = condition.match(/^contains\(\s*@([\w:.-]+)\s*,\s*['"]([^'"]*)['"]\s*\)$/))) {
        selector += `[${match[1]}*="${match[2]}"]`;
      } else if ((match = condition.match(/^starts-with\(\s*@([\w:.-]+)\s*,\s*['"]([^'"]*)['"]\s*\)$/))) {
        selector += `[${match[1]}^="${match[2]}"]`;
      } else if ((match = condition.match(/^contains\(\s*(?:\.|text\(\))\s*,\s*['"]([^'"]*)['"]\s*\)$/))) {
        selector += `:contains("${match[1]}")`;
      } else if (/^\d+$/.test(condition)) selector += `:nth-of-type(${condition})`;
      else if (condition === 'last()') selector += ':last-child';
      else if (/^@[\w:.-]+$/.test(condition)) selector += `[${condition.slice(1)}]`;
    }
    return selector;
  });
  return (descendants ? '' : ':root > ') + parts.join(' > ').replace(/ > /g, ' ') + '@' + tail;
}

function combinedRuleValue(source, raw, input, env, all) {
  for (const separator of ['||', '&&', '%%']) {
    const parts = splitCombinedRule(raw, separator);
    if (parts.length < 2) continue;
    const groups = parts.map(part => {
      const result = ruleValue(source, part, input, env, all);
      return Array.isArray(result) ? result : (result === '' || result === null ? [] : [result]);
    });
    if (separator === '||') {
      const selected = groups.find(group => group.length > 0) || [];
      return all ? selected : (selected[0] === undefined ? '' : selected[0]);
    }
    if (separator === '%%') {
      const output = [];
      const length = Math.max(...groups.map(group => group.length));
      for (let index = 0; index < length; index++) {
        for (const group of groups) if (group[index] !== undefined) output.push(group[index]);
      }
      return all ? output : output.join('\n');
    }
    const output = groups.flat();
    return all ? output : output.join('\n');
  }
  return null;
}

function ruleValue(source, rule, input, env, all) {
  const raw = text(rule).trim();
  if (!raw) return all ? [] : '';
  const combined = combinedRuleValue(source, raw, input, env, all);
  if (combined !== null) return combined;
  if (raw.includes('{{')) return renderTemplate(source, raw, Object.assign({}, env, { result: input }));
  if (/^<js>/i.test(raw)) {
    const close = raw.toLowerCase().indexOf('</js>');
    if (close < 0) throw new Error('阅读 JS 规则缺少 </js>');
    const value = evaluateJs(source, raw.slice(0, close + 5),
      Object.assign({}, env, { result: input, src: input }));
    const tail = raw.slice(close + 5).trim();
    return tail ? ruleValue(source, tail, value, Object.assign({}, env, { result: value }), all) : value;
  }
  if (/^@js:/i.test(raw)) {
    return evaluateJs(source, raw, Object.assign({}, env, { result: input, src: input }));
  }
  const replacement = splitReplacement(raw);
  let value;
  if (/^@json:/i.test(replacement.rule) || /^\$[.[]/.test(replacement.rule) ||
    (/^[A-Za-z_$][\w$-]*$/.test(replacement.rule) &&
      (typeof input === 'object' || /^\s*[\[{]/.test(text(input))))) {
    value = jsonPath(input, replacement.rule);
  } else if (/^@xpath:/i.test(replacement.rule) || /^\//.test(replacement.rule)) {
    value = defaultSelector(xpathSelector(replacement.rule), input, all, false);
  } else {
    value = defaultSelector(replacement.rule, input, all,
      sourceRuleTemplate(source).version === 'legacy');
  }
  if (Array.isArray(value)) return value.map(item => replaceRule(item, replacement));
  return replaceRule(value === null || value === undefined ? '' : value, replacement);
}

function ruleList(source, rule, input, env) {
  let raw = text(rule).trim();
  const reverse = raw.startsWith('-') && raw.length > 1;
  if (reverse) raw = raw.slice(1).trim();
  if (raw.startsWith(':')) {
    const matches = text(input).match(new RegExp(raw.slice(1), 'g')) || [];
    return reverse ? matches.reverse() : matches;
  }
  const value = ruleValue(source, raw, input, env, true);
  if (Array.isArray(value)) return reverse ? value.reverse() : value;
  if (value === null || value === undefined || value === '') return [];
  return [value];
}

function sourceHeaders(source, env) {
  const raw = source.header && /^<js>|^@js:/i.test(text(source.header).trim()) ?
    evaluateJs(source, source.header, env) : source.header;
  const headers = jsonObject(raw, {});
  if (sourceRuleTemplate(source).version === 'legacy' &&
      !Object.keys(headers).some(name => name.toLowerCase() === 'user-agent')) {
    headers['User-Agent'] = 'Mozilla/5.0 (Linux; Android 10; Mobile) AppleWebKit/537.36 ' +
      '(KHTML, like Gecko) Chrome/143.0.0.0 Mobile Safari/537.36';
  }
  const loginHeader = jsonObject(reader.storage.get(sourceStorageKey(source, 'loginHeader')), {});
  return Object.assign(headers, loginHeader);
}

function loadByUrl(source, rule, env, webOptions) {
  const rendered = urlCompat(evaluateUrl(source, rule, env), env && env.baseUrl || sourceNetworkUrl(source));
  if (/^data:/i.test(rendered)) return { body: rendered, url: rendered };
  const request = parseAjaxRequest(rendered, source, env);
  request.headers = Object.assign({}, sourceHeaders(source, env), request.headers || {});
  if (sourceRuleTemplate(source).version === 'legacy' && request.method === 'POST' &&
      typeof request.body === 'string' &&
      !Object.keys(request.headers).some(name => name.toLowerCase() === 'content-type')) {
    request.headers['Content-Type'] = 'application/x-www-form-urlencoded';
  }
  const web = object(webOptions);
  const javaScript = text(request.webJs || web.webJs);
  const sourceRegex = text(web.sourceRegex);
  if (request.webView || javaScript || sourceRegex) {
    if (!reader.webview || typeof reader.webview.execute !== 'function') {
      throw new Error('该书源需要 WebJs 动态页面执行；当前插件宿主未提供 WebView 能力');
    }
    const result = reader.webview.execute({ url: request.url, headers: request.headers,
      javaScript: javaScript || 'document.documentElement.outerHTML', sourceRegex,
      delayMs: request.webViewDelayTime || Number(web.delayMs || (javaScript ? 0 : 900)) });
    return { body: text(result && (result.body !== undefined ? result.body : result.value)),
      url: text(result && result.url) || request.url };
  }
  let response = null, lastError = null;
  for (let attempt = 0; attempt <= request.retry; attempt++) {
    try {
      response = reader.http.fetch(request);
      if (response && response.status >= 200 && response.status < 400) break;
      lastError = new Error('HTTP ' + (response ? response.status : 'unknown'));
    } catch (error) { lastError = error; }
  }
  if (!response || response.status < 200 || response.status >= 400) {
    throw new Error('书源请求失败：' + text(lastError && lastError.message ? lastError.message : lastError));
  }
  let body = response.body;
  if (request.bodyJs) {
    body = text(evaluateJs(source, request.bodyJs,
      Object.assign({}, env, { result: body, src: body, baseUrl: response.url || request.url })));
  }
  return { body, url: response.url || request.url };
}

function loginScript(source) {
  const raw = text(source.loginUrl);
  if (/^@js:/i.test(raw)) return raw.slice(4);
  if (/^<js>/i.test(raw) && /<\/js>\s*$/i.test(raw)) return raw.slice(4, raw.lastIndexOf('<'));
  return raw;
}

function rewriteReadingImportLinks(target) {
  const raw = text(target);
  const matched = raw.match(/^(data:text\/html(?:;charset=[A-Za-z0-9._-]+)?;base64,)([A-Za-z0-9+/=\r\n]+)$/i);
  if (!matched) return raw;
  let html = '';
  try { html = base64Utf8(matched[2]); } catch (_) { return raw; }
  const rewritten = html.replace(/yuedu:\/\/booksource\/importonline\?src=/gi,
    'fishreader-plugin-action://legado/importonline?src=');
  return rewritten === html ? raw : matched[1] + utf8Base64(rewritten);
}

function sourceUpdateUrlFromBrowser(browserResult) {
  const raw = text(browserResult && browserResult.url);
  const matched = raw.match(/^fishreader-plugin-action:\/\/legado\/importonline\?src=([^&#]+)$/i);
  if (!matched) return '';
  try { return decodeURIComponent(matched[1]); } catch (_) { return ''; }
}

function downloadSourceUpdate(source, browserResult) {
  const target = sourceUpdateUrlFromBrowser(browserResult);
  if (!target) return undefined;
  if (!/^https?:\/\//i.test(target)) throw new Error('更新书源地址仅支持 HTTP/HTTPS');
  const response = reader.http.fetch({ url: target, method: 'GET', headers: {} });
  if (!response || response.status < 200 || response.status >= 300) {
    throw new Error('更新书源下载失败：HTTP ' + text(response && response.status));
  }
  let decoded = null;
  try { decoded = JSON.parse(text(response.body).replace(/^\uFEFF/, '')); }
  catch (error) { throw new Error('更新书源不是有效 JSON：' + text(error && error.message)); }
  const sources = normalizeImportedSourceList(decoded);
  if (sources.length === 0) throw new Error('更新文件中没有有效的阅读 3 书源');
  const currentKey = text(source.bookSourceUrl || source.bookSourceName);
  const replacement = sources.find(item =>
    text(item.bookSourceUrl || item.bookSourceName) === currentKey) || sources[0];
  if (source.enabled === false && replacement.enabled === undefined) replacement.enabled = false;
  return sources;
}

function executeLoginAction(source, input) {
  const context = loginContext(source, input);
  const loginData = object(input.loginData);
  context.sourceApi.putLoginInfo(JSON.stringify(loginData));
  const browserSessionKey = 'legado.browserSession.v1';
  const savedSession = input.browserCompleted === true ?
    object(reader.storage.get(browserSessionKey)) : {};
  const sessionTime = Number(savedSession.time || Date.now());
  const sessionRandom = Number(savedSession.random === undefined ? Math.random() : savedSession.random);
  const NativeDate = Date;
  const ReplayDate = function ReplayDate(...args) {
    if (!(this instanceof ReplayDate)) return NativeDate(...args);
    return args.length === 0 ? new NativeDate(sessionTime) : new NativeDate(...args);
  };
  ReplayDate.now = () => sessionTime;
  ReplayDate.parse = NativeDate.parse;
  ReplayDate.UTC = NativeDate.UTC;
  ReplayDate.prototype = NativeDate.prototype;
  const ReplayMath = Object.create(Math);
  ReplayMath.random = () => sessionRandom;
  const action = text(input.action) === '__login__' ?
    "if(typeof login==='function'){login.apply(this)}else{throw new Error('Function login not implemented')}" :
    text(input.action);
  try {
    const program = 'globalThis.java=java;globalThis.source=source;globalThis.cookie=cookie;' +
      'globalThis.cache=cache;globalThis.isLongClick=isLongClick;' + text(source.jsLib) + '\n' + bindDeclaredFunctions(source.jsLib) +
      '\n' + loginScript(source) + '\n' + bindDeclaredFunctions(loginScript(source)) +
      '\nreturn eval(' + JSON.stringify(action) + ');';
    const runner = new Function('java', 'source', 'cookie', 'cache', 'result', 'baseUrl',
      'Packages', 'JavaImporter', 'Date', 'Math', 'isLongClick', program);
    const javaImporter = function JavaImporter() { this.importClass = () => true; };
    runner.call({ java: context.javaApi, source: context.sourceApi, cookie: context.cookieApi,
      cache: context.cacheApi }, context.javaApi, context.sourceApi, context.cookieApi,
      context.cacheApi, loginData, text(source.bookSourceUrl), undefined, javaImporter,
      ReplayDate, ReplayMath, input.isLongClick === true);
    const pendingBrowser = context.pendingBrowser();
    const sourceUpdate = input.browserCompleted === true ?
      downloadSourceUpdate(source, object(reader.storage.get('legado.browserResult.v1'))) : undefined;
    if (pendingBrowser !== null && input.browserCompleted !== true) {
      reader.storage.set(browserSessionKey, { time: sessionTime, random: sessionRandom });
    } else {
      reader.storage.set(browserSessionKey, null);
      reader.storage.set('legado.browserResult.v1', null);
    }
    if (sourceUpdate !== undefined) context.messages.push('书源更新已下载，等待确认新增域名并替换');
    return { messages: context.messages, browser: pendingBrowser || undefined,
      sourceUpdate, uiEffects: context.uiEffects };
  } catch (error) {
    throw error;
  }
}

