function exploreEntries(value) {
  const raw = text(value).trim();
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    if (Array.isArray(parsed)) return parsed.map(item => object(item));
  } catch (_) {}
  return raw.split(/\r?\n|&&/).map(item => item.trim()).filter(Boolean).map(item => {
    const marker = item.indexOf('::');
    return marker >= 0 ? { title: item.slice(0, marker).trim(), url: item.slice(marker + 2).trim() } :
      { title: item, url: item };
  });
}

function loadExploreMenuEntries(source, input) {
  const env = { key: text(input && input.category), page: Number(input && input.page || 1), result: null,
    baseUrl: sourceNetworkUrl(source) };
  const rawExploreUrl = text(source.exploreUrl).trim();
  const menu = /^<js>/i.test(rawExploreUrl) || /^@js:/i.test(rawExploreUrl) ?
    text(evaluateJs(source, rawExploreUrl, env)) : rawExploreUrl;
  return { entries: exploreEntries(menu), env, rawExploreUrl };
}

function exploreEntryKey(item, index) {
  return `dynamic:${index}:` + sourceIdentity({
    bookSourceUrl: text(item.title) + '\n' + text(item.url)
  }).replace(/^legado\.source\./, '');
}

function exploreGroupTitle(value) {
  const title = text(value).trim();
  const meaningful = title.match(/[\u3400-\u9fffA-Za-z0-9](?:.*[\u3400-\u9fffA-Za-z0-9])?/);
  return meaningful ? meaningful[0].trim() : title;
}

function isExploreGroupHeading(item) {
  const title = text(item && item.title).trim();
  if (!title || text(item && item.url).trim()) return false;
  return /[\u3400-\u9fffA-Za-z0-9]/.test(title);
}

function exploreMenuItems(entries) {
  const firstHeading = entries.findIndex(item => isExploreGroupHeading(item));
  if (firstHeading < 0) {
    return entries.map((item, index) => ({ item, index, group: '' }));
  }
  const result = [];
  let group = '';
  for (let index = firstHeading; index < entries.length; index++) {
    const item = entries[index];
    if (isExploreGroupHeading(item)) {
      group = exploreGroupTitle(item.title);
      continue;
    }
    if (!group || !text(item && item.url).trim()) continue;
    result.push({ item, index, group });
  }
  return result;
}

function selectExploreUrl(source, input) {
  const loadedMenu = loadExploreMenuEntries(source, input);
  const entries = loadedMenu.entries;
  const env = loadedMenu.env;
  const rawExploreUrl = loadedMenu.rawExploreUrl;
  if (entries.length === 0) return evaluateUrl(source, rawExploreUrl, env);
  const category = text(input.category);
  const selected = entries.find((item, index) => exploreEntryKey(item, index) === category) ||
    entries.find(item => text(item.title) === category || text(item.url) === category) ||
    entries.find(item => /^https?:\/\//i.test(text(item.url))) || entries[0];
  const selectedUrl = text(selected.url);
  const renderedUrl = evaluateUrl(source, selectedUrl, env);
  if (!renderedUrl && /\bjava\.(?:startBrowser|startBrowserAwait|startBrowserDp|showBrowser|showReadingBrowser)\s*\(/i
    .test(selectedUrl)) {
    throw new Error(`发现入口“${text(selected.title) || '网页操作'}”需要登录或网页交互，` +
      '请先在书源管理页执行对应操作，再刷新发现');
  }
  return renderedUrl;
}

