module.exports.detail = async input => {
  const source = sourceForInput(input);
  const identity = text(input.bookKey || input.bookUrl);
  const saved = stored(identity);
  if (!saved.bookUrl) throw new Error('书籍标识已失效，请重新搜索');
  const rules = sourceRuleTemplate(source).bookInfo;
  const fingerprint = ruleFingerprint([saved.bookUrl, rules, text(source.jsLib)]);
  const cache = stored(detailCacheKey(identity));
  if (input.forceRefresh !== true && text(cache.fingerprint) === fingerprint &&
      cache.detail && cache.result) {
    const restored = Object.assign({}, saved, object(cache.detail));
    reader.storage.set(identity, restored);
    return object(cache.result);
  }
  const loaded = loadByUrl(source, saved.bookUrl, { result: saved.raw, book: saved,
    baseUrl: saved.bookUrl });
  let result = loaded.body;
  const env = { result, src: loaded.body, baseUrl: loaded.url, book: saved };
  if (rules.init) result = ruleValue(source, rules.init, result, env, false);
  const fieldEnv = Object.assign({}, env, { result });
  const detail = Object.assign({}, saved, {
    raw: result,
    title: text(ruleValue(source, rules.name, result, fieldEnv, false)) || text(saved.title),
    author: text(ruleValue(source, rules.author, result, fieldEnv, false)) || text(saved.author),
    intro: text(ruleValue(source, rules.intro, result, fieldEnv, false)),
    coverUrl: urlCompat(ruleValue(source, rules.coverUrl, result, fieldEnv, false), loaded.url),
    tocSourceUrl: urlCompat(ruleValue(source, rules.tocUrl, result, fieldEnv, false), loaded.url),
    downloadUrls: [], canReName: false
  });
  const downloadUrls = ruleValue(source, rules.downloadUrls, result, fieldEnv, true);
  detail.downloadUrls = (Array.isArray(downloadUrls) ? downloadUrls : [downloadUrls])
    .map(item => urlCompat(item, loaded.url)).filter(Boolean);
  detail.canReName = text(rules.canReName).trim().length > 0;
  if (!detail.tocSourceUrl) detail.tocSourceUrl = saved.bookUrl;
  const output = detailResult(identity, detail, source, rules, result, fieldEnv);
  const cachedDetail = Object.assign({}, detail);
  reader.storage.set(identity, detail);
  reader.storage.set(detailCacheKey(identity),
    { fingerprint, updatedAtMs: Date.now(), detail: cachedDetail, result: output });
  return output;
};

module.exports.catalog = async input => {
  const source = sourceForInput(input);
  const identity = text(input.bookKey || input.tocUrl || input.bookUrl);
  const saved = stored(identity);
  if (!saved.tocSourceUrl) throw new Error('目录地址已失效，请重新打开详情');
  const rules = sourceRuleTemplate(source).toc;
  const fingerprint = ruleFingerprint([saved.tocSourceUrl, rules, text(source.jsLib)]);
  if (input.forceRefresh !== true) {
    const cache = cachedCatalog(identity, fingerprint);
    if (cache !== null) return cache;
  }
  const executionState = { storageValues: {} };
  if (rules.preUpdateJs) evaluateJs(source, rules.preUpdateJs,
    { result: saved.raw, book: saved, baseUrl: saved.tocSourceUrl,
      __legadoExecutionState: executionState });
  const pages = [];
  const visited = new Set();
  let pageUrl = saved.tocSourceUrl;
  for (let page = 1; page <= 64 && pageUrl && !visited.has(pageUrl); page++) {
    visited.add(pageUrl);
    const loaded = loadByUrl(source, pageUrl,
      { result: saved.raw, book: saved, page, baseUrl: pageUrl,
        __legadoExecutionState: executionState });
    const env = { result: loaded.body, src: loaded.body, book: saved, page, baseUrl: loaded.url,
      __legadoExecutionState: executionState };
    const items = ruleList(source, rules.chapterList, loaded.body, env);
    for (const raw of items) pages.push({ raw, baseUrl: loaded.url, env });
    if (!rules.nextTocUrl || pages.length >= 20000) break;
    const next = ruleValue(source, rules.nextTocUrl, loaded.body, env, false);
    const nextUrl = urlCompat(Array.isArray(next) ? next[0] : next, loaded.url);
    if (!nextUrl || visited.has(nextUrl)) break;
    pageUrl = nextUrl;
  }
  const chapters = pages.slice(0, 20000).map((pageItem, index) => {
    const raw = pageItem.raw;
    const rowEnv = Object.assign({}, pageItem.env,
      { result: raw, chapter: object(raw), index: index + 1, gInt: index + 1 });
    const chapterUrl = urlCompat(ruleValue(source, rules.chapterUrl, raw, rowEnv, false), pageItem.baseUrl);
    let title = text(ruleValue(source, rules.chapterName, raw, rowEnv, false)) || ('第 ' + (index + 1) + ' 章');
    const chapter = { chapterKey: '', bookKey: identity, sourceKey: text(saved.sourceKey), chapterUrl, raw, index,
      title, updateTime: text(ruleValue(source, rules.updateTime, raw, rowEnv, false)),
      isVolume: /^(true|1)$/i.test(text(ruleValue(source, rules.isVolume, raw, rowEnv, false))),
      isLocked: /^(true|1)$/i.test(text(ruleValue(source, rules.isVip || rules.isPay, raw, rowEnv, false))) };
    if (rules.formatJs) {
      const formatted = evaluateJs(source, rules.formatJs,
        Object.assign({}, rowEnv, { title, chapter, index: index + 1, gInt: index + 1 }));
      if (formatted !== undefined && formatted !== null && text(formatted)) title = text(formatted);
      chapter.title = title;
    }
    return chapter;
  });
  for (let index = 0; index < chapters.length; index++) {
    chapters[index].nextChapterUrl = index + 1 < chapters.length ?
      text(chapters[index + 1].chapterUrl) : '';
  }
  return storeCatalogSnapshot(source, identity, fingerprint, chapters);
};

module.exports.content = async input => {
  const source = sourceForInput(input);
  const chapterIdentity = text(input.chapterKey || input.chapterUrl);
  let saved = stored(chapterIdentity);
  if (!saved.chapterUrl) saved = snapshotChapter(chapterIdentity);
  if (!saved.chapterUrl) throw new Error('章节标识已失效，请重新打开目录');
  const bookIdentity = text(saved.bookKey);
  const book = Object.assign({}, stored(bookIdentity), object(stored(detailCacheKey(bookIdentity)).detail));
  const rules = sourceRuleTemplate(source).content;
  const contents = [];
  const visited = new Set();
  let pageUrl = saved.chapterUrl, finalBaseUrl = saved.chapterUrl;
  for (let page = 1; page <= 64 && pageUrl && !visited.has(pageUrl); page++) {
    visited.add(pageUrl);
    const loaded = loadByUrl(source, pageUrl, { result: saved.raw, book, chapter: saved,
      title: saved.title, page, nextChapterUrl: saved.nextChapterUrl, baseUrl: pageUrl },
      { webJs: rules.webJs, sourceRegex: rules.sourceRegex });
    finalBaseUrl = loaded.url;
    const env = { result: loaded.body, src: loaded.body, book, chapter: saved, page,
      nextChapterUrl: saved.nextChapterUrl, title: saved.title, baseUrl: loaded.url };
    contents.push(text(ruleValue(source, rules.content, loaded.body, env, false)));
    if (text(rules.subContent).trim()) {
      const subContent = text(ruleValue(source, rules.subContent, loaded.body, env, false));
      if (subContent) contents.push(subContent);
    }
    if (!rules.nextContentUrl) break;
    const next = ruleValue(source, rules.nextContentUrl, loaded.body, env, false);
    const nextUrl = urlCompat(Array.isArray(next) ? next[0] : next, loaded.url);
    if (!nextUrl || visited.has(nextUrl) || nextUrl === saved.nextChapterUrl) break;
    pageUrl = nextUrl;
  }
  let content = contents.filter(Boolean).join('\n');
  if (rules.replaceRegex) {
    try { content = content.replace(new RegExp(text(rules.replaceRegex), 'g'), ''); } catch (_) {}
  }
  const title = text(rules.title).trim() ? text(ruleValue(source, rules.title, content,
      { result: content, src: content, book, chapter: saved, title: saved.title,
        baseUrl: finalBaseUrl }, false)) : text(saved.title);
  const structured = structuredChapterContent(content);
  if (structured) return Object.assign(structured, {
    baseUrl: finalBaseUrl, title, imageStyle: text(rules.imageStyle)
  });
  return { content, contentType: 'text', baseUrl: finalBaseUrl,
    title, imageStyle: text(rules.imageStyle) };
};

module.exports.loginCheck = async input => {
  const source = sourceForInput(input);
  if (text(source.loginCheckJs).trim()) {
    const value = evaluateJs(source, source.loginCheckJs, { result: input || {},
      baseUrl: sourceNetworkUrl(source) });
    if (value && typeof value === 'object') {
      return { loggedIn: value.loggedIn === true, message: text(value.message) };
    }
    return { loggedIn: value === true || /^(true|1|ok)$/i.test(text(value)), message: text(value) };
  }
  const context = loginContext(source, input || {});
  const hasCookie = text(context.cookieApi.getCookie(source.bookSourceUrl)).length > 0;
  const hasLoginInfo = text(context.sourceApi.getLoginInfo()).length > 0;
  return { loggedIn: hasCookie || hasLoginInfo, message: hasCookie ? 'Cookie 已存在' :
    (hasLoginInfo ? '登录信息已保存' : '尚未登录') };
};

module.exports.manageSearchTarget = async input => {
  const sourceKey = text(input.sourceKey).trim();
  const action = text(input.action).trim();
  const databaseSource = databaseSourceByKey(sourceKey);
  if (databaseSource) {
    if (action === 'disable') {
      databaseSource.enabled = false;
      if (!databaseExecute(
        'UPDATE legado_sources SET enabled = 0, source_json = ?, updated_at_ms = ? WHERE source_key = ?',
        [JSON.stringify(databaseSource), Date.now(), sourceKey])) return { changed: false };
    } else if (action === 'delete') {
      const prefix = sourceStorageKey(databaseSource, '');
      ['loginInfo', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
      if (!databaseExecute('DELETE FROM legado_sources WHERE source_key = ?', [sourceKey])) {
        return { changed: false };
      }
    } else {
      throw new Error('不支持的书源处理动作');
    }
    const active = text(reader.storage.get(ACTIVE_SOURCE_KEY) ||
      reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
    if (active === sourceKey) {
      reader.storage.set(ACTIVE_SOURCE_KEY, '');
      reader.storage.set(LEGACY_ACTIVE_SOURCE_KEY, '');
      reader.storage.set(ACTIVE_SOURCE_RECORD_KEY, '');
    }
    return { changed: true };
  }
  const sources = importedSources();
  const index = sources.findIndex(item =>
    text(item.bookSourceUrl || item.bookSourceName) === sourceKey);
  if (index < 0) return { changed: false };
  if (action === 'disable') {
    sources[index] = Object.assign({}, sources[index], { enabled: false });
  } else if (action === 'delete') {
    const source = sources[index];
    sources.splice(index, 1);
    const prefix = sourceStorageKey(source, '');
    ['loginInfo', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
  } else {
    throw new Error('不支持的书源处理动作');
  }
  reader.storage.set(SOURCE_KEY, sources);
  reader.storage.set(LEGACY_SOURCE_KEY, []);
  const active = text(reader.storage.get(ACTIVE_SOURCE_KEY) || reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
  if (active === sourceKey) {
    reader.storage.set(ACTIVE_SOURCE_KEY, '');
    reader.storage.set(LEGACY_ACTIVE_SOURCE_KEY, '');
    reader.storage.set(ACTIVE_SOURCE_RECORD_KEY, '');
  }
  return { changed: true };
};

module.exports.manage = async input => {
  const mode = text(input.mode);
  if (mode === 'deleteSources') {
    const sourceKeys = [...new Set((Array.isArray(input.sourceKeys) ? input.sourceKeys : [])
      .map(value => text(value).trim()).filter(Boolean))];
    if (!sourceKeys.length || sourceKeys.length > 5000) throw new Error('批量删除书源数量无效');
    sourceKeys.forEach(sourceKey => {
      const prefix = sourceStorageKey({ bookSourceUrl: sourceKey }, '');
      ['loginInfo', 'loginHeader', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
    });
    if (reader.database && typeof reader.database.batch === 'function') {
      for (let offset = 0; offset < sourceKeys.length; offset += 500) {
        reader.database.batch({ statements: sourceKeys.slice(offset, offset + 500).map(sourceKey => ({
          sql: 'DELETE FROM legado_sources WHERE source_key = ?', bindArgs: [sourceKey]
        })) });
      }
    } else {
      sourceKeys.forEach(sourceKey => {
        if (!databaseExecute('DELETE FROM legado_sources WHERE source_key = ?', [sourceKey])) {
          throw new Error('删除书源失败：' + sourceKey);
        }
      });
    }
    const active = text(reader.storage.get(ACTIVE_SOURCE_KEY) ||
      reader.storage.get(LEGACY_ACTIVE_SOURCE_KEY));
    if (sourceKeys.includes(active)) {
      reader.storage.set(ACTIVE_SOURCE_KEY, '');
      reader.storage.set(LEGACY_ACTIVE_SOURCE_KEY, '');
      reader.storage.set(ACTIVE_SOURCE_RECORD_KEY, '');
    }
    return { deleted: sourceKeys.length };
  }
  const sourceKey = text(input.sourceKey);
  const source = sourceByKey(sourceKey);
  if (!source) throw new Error('书源不存在或已被删除');
  if (mode === 'getLoginInfo') {
    return jsonObject(reader.storage.get(sourceStorageKey(source, 'loginInfo')), {});
  }
  if (mode === 'getLoginUi') return evaluateLoginUi(source, input);
  if (mode === 'getLoginLabels') return evaluateLoginLabels(source, input);
  if (mode === 'deleteSource') {
    const prefix = sourceStorageKey(source, '');
    ['loginInfo', 'variable'].forEach(name => reader.storage.set(prefix + name, ''));
    return { deleted: true };
  }
  if (mode === 'loginAction') return executeLoginAction(source, input);
  throw new Error('不支持的插件管理操作');
};
